mapper.select:
SELECT id, role_code, role_name, description, status, created_at, updated_at, is_deleted AS isDeleted, deleted_at AS deletedAt, deleted_by AS deletedBy FROM sys_role WHERE role_code IN
#{code}
ORDER BY id ASC

SELECT id, role_code, role_name, description, status, created_at, updated_at, is_deleted AS isDeleted, deleted_at AS deletedAt, deleted_by AS deletedBy FROM sys_role r
AND (r.role_code LIKE CONCAT('%', #{keyword}, '%') OR r.role_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.id ASC LIMIT #{limit}

SELECT rp.role_id AS roleId, COUNT(*) AS cnt FROM sys_role_permission rp WHERE rp.role_id IN
#{roleId}
AND rp.is_deleted = 0 GROUP BY rp.role_id

SELECT ur.role_id AS roleId, COUNT(*) AS cnt FROM sys_user_role ur INNER JOIN sys_user u ON u.id = ur.user_id WHERE ur.role_id IN
#{roleId}
AND ur.is_deleted = 0 AND u.is_deleted = 0 GROUP BY ur.role_id

SELECT rp.role_id AS roleId, p.id AS permissionId, p.perm_code AS permissionCode, p.perm_name AS permissionName FROM sys_role_permission rp INNER JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id IN
#{roleId}
AND rp.is_deleted = 0 AND p.is_deleted = 0 ORDER BY rp.role_id ASC, p.sort_no ASC, p.id ASC

mapper.update:
UPDATE sys_role
role_name = #{roleName}, description = #{description}, status = #{status},
WHERE id = #{id}

UPDATE sys_role_permission SET is_deleted = 1, deleted_at = NOW(6), deleted_by = COALESCE(#{operatorId}, 'DB') WHERE role_id = #{roleId} AND is_deleted = 0
AND permission_id NOT IN
#{permissionId}

