SELECT id FROM sys_permission WHERE is_deleted = 0 AND perm_code IN
#{code}
ORDER BY id ASC

SELECT id, perm_code, perm_name, perm_type, parent_id, path, component, icon, sort_no, created_at FROM sys_permission WHERE is_deleted = 0 AND perm_code IN
#{code}
ORDER BY sort_no ASC, id ASC

SELECT id, perm_code, perm_name, perm_type, parent_id, path, component, icon, sort_no, created_at FROM sys_permission WHERE id IN
#{id}
ORDER BY sort_no ASC, id ASC

SELECT id FROM sys_role WHERE is_deleted = 0 AND role_code IN
#{code}
ORDER BY id ASC

SELECT role_code FROM sys_role WHERE status = 1 AND is_deleted = 0 AND role_code IN
#{code}
ORDER BY id ASC

SELECT id, role_code, role_name, description, status, created_at, updated_at,
       is_deleted AS isDeleted, deleted_at AS deletedAt, deleted_by AS deletedBy
FROM sys_role WHERE id = #{id}
